enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case WrongCredentials
    case UnsupportedDatabase
    case CorruptedDatabase
    case ReadFailed
    case WriteFailed
    case Conflict
    case InvalidOperation

    

    

    
