        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .WrongCredentials
        case 2: return .UnsupportedDatabase
        case 3: return .CorruptedDatabase
        case 4: return .ReadFailed
        case 5: return .WriteFailed
        case 6: return .Conflict
        case 7: return .InvalidOperation

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

